/* From Uiverse.io by mykill1 - Tags: card */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 254px;
  border-radius: 10px;
  background: #ae3737;
  overflow: hidden;
  box-shadow: inset 27px 27px 54px #7a2727, inset -27px -27px 54px #e24848;
}

.__UIV_SCOPE__ .content {
  width: 160px;
  height: 220px;
  position: relative;
  margin-top: 16px;
  margin-left: 15px;
  border: none;
  border-radius: 10px;
  background: #ae3737;
  background: linear-gradient(45deg, #9d3232, #ba3b3b);
  box-shadow: 27px -27px 54px #7a2727,
             -27px 27px 54px #e24848;
}

.__UIV_SCOPE__ content :hover {
  border: 1px solid #7a2727;
}

.__UIV_SCOPE__ .card :hover {
  border: 1px solid #7a2727;
}
